CREATE OR REPLACE FUNCTION public.salvar_lista_treinamento(p_id uuid,p_dados jsonb,p_participantes jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v_id uuid; v_owner uuid; v_company uuid; p jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão expirada'; END IF; IF jsonb_typeof(p_participantes)<>'array' THEN RAISE EXCEPTION 'Participantes inválidos'; END IF; IF p_id IS NULL THEN v_owner:=auth.uid(); v_company:=public.active_company_id(); INSERT INTO public.listas_presenca(user_id,company_id,tema) VALUES(v_owner,v_company,'') RETURNING id INTO v_id; ELSE SELECT id,user_id,company_id INTO v_id,v_owner,v_company FROM public.listas_presenca WHERE id=p_id FOR UPDATE; IF v_id IS NULL OR (v_owner<>auth.uid() AND NOT public.is_admin_principal(auth.uid())) THEN RAISE EXCEPTION 'Sem permissão para editar esta lista'; END IF; END IF; IF trim(coalesce(p_dados->>'nome_treinamento',''))='' THEN RAISE EXCEPTION 'Informe o nome do treinamento'; END IF; UPDATE public.listas_presenca SET local=nullif(trim(p_dados->>'local'),''),data=nullif(p_dados->>'data','')::date,empresa=upper(nullif(trim(p_dados->>'empresa'),'')),horario=nullif(p_dados->>'horario',''),horario_inicial=nullif(p_dados->>'horario_inicial',''),horario_final=nullif(p_dados->>'horario_final',''),carga_horaria=nullif(p_dados->>'carga_horaria',''),tema=upper(trim(coalesce(p_dados->>'tema',''))),nome_treinamento=upper(trim(p_dados->>'nome_treinamento')),modo_assinatura=coalesce(p_dados->>'modo_assinatura','manual') WHERE id=v_id; DELETE FROM public.lista_presenca_participantes WHERE lista_id=v_id AND id NOT IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(p_participantes) x WHERE nullif(x->>'id','') IS NOT NULL); FOR p IN SELECT value FROM jsonb_array_elements(p_participantes) LOOP IF trim(coalesce(p->>'nome',''))='' THEN RAISE EXCEPTION 'Informe o nome do participante'; END IF; IF nullif(p->>'employee_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.employees WHERE id=(p->>'employee_id')::uuid AND company_id=v_company) THEN RAISE EXCEPTION 'Colaborador não pertence à empresa da lista'; END IF; IF nullif(p->>'id','') IS NOT NULL THEN UPDATE public.lista_presenca_participantes SET nome=upper(trim(p->>'nome')),funcao=upper(nullif(trim(p->>'funcao'),'')),ordem=(p->>'ordem')::integer WHERE id=(p->>'id')::uuid AND lista_id=v_id; IF NOT FOUND THEN RAISE EXCEPTION 'Participante inválido'; END IF; ELSE INSERT INTO public.lista_presenca_participantes(lista_id,user_id,company_id,employee_id,ordem,nome,funcao) VALUES(v_id,v_owner,v_company,nullif(p->>'employee_id','')::uuid,(p->>'ordem')::integer,upper(trim(p->>'nome')),upper(nullif(trim(p->>'funcao'),''))); END IF; END LOOP; RETURN v_id; END $$;
CREATE FUNCTION public.company_logo_for_owner(p_owner uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.empresa_logo FROM public.profiles p WHERE p.id=p_owner AND (p.id=auth.uid() OR public.is_admin_principal(auth.uid()) OR EXISTS(SELECT 1 FROM public.company_memberships m WHERE m.user_id=p.id AND public.can_read_company(m.company_id))) $$;
REVOKE ALL ON FUNCTION public.company_logo_for_owner(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.company_logo_for_owner(uuid) TO authenticated;
REVOKE SELECT ON public.company_invitations FROM authenticated;
GRANT SELECT(id,company_id,email,invited_by,expires_at,accepted_at,created_at) ON public.company_invitations TO authenticated;
-- Uniqueness is organization-specific; display names do not confer access.
CREATE FUNCTION public.validate_company_employee_cpf() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.cpf IS NOT NULL AND EXISTS(SELECT 1 FROM public.employees e WHERE e.company_id=NEW.company_id AND e.contractor_id IS NOT DISTINCT FROM NEW.contractor_id AND regexp_replace(e.cpf,'[^0-9]','','g')=regexp_replace(NEW.cpf,'[^0-9]','','g') AND e.id<>NEW.id) THEN RAISE EXCEPTION 'Já existe um colaborador com este CPF nesta empresa'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_company_employee_cpf() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_company_employee_cpf BEFORE INSERT OR UPDATE ON public.employees FOR EACH ROW EXECUTE FUNCTION public.validate_company_employee_cpf();